public final class FindMeClientAbilityActionRegistry {
    private static final List<Entry> ENTRIES = new CopyOnWriteArrayList<Entry>();

    private FindMeClientAbilityActionRegistry() {
    }

    public static void register(ResourceLocation id, int order, Function<CompanionCommandTarget, Component> label, Predicate<CompanionCommandTarget> available, Predicate<CompanionCommandTarget> activate) {
        Objects.requireNonNull(id, "id");
