        Objects.requireNonNull(activate, "activate");
        ENTRIES.removeIf(entry -> entry.id.equals((Object)id));
        ENTRIES.add(new Entry(id, order, label, available, activate));
    }

    public static List<Entry> entries() {
        ArrayList<Entry> result = new ArrayList<Entry>(ENTRIES);
        result.sort(Comparator.comparingInt(Entry::order).thenComparing(entry -> entry.id.toString()));
        return List.copyOf(result);
    }

    private static void quarantine(ResourceLocation id, String operation, RuntimeException exception) {
        ENTRIES.removeIf(entry -> entry.id.equals((Object)id));
        FindMeMod.LOGGER.error("FindMe removed failing client ability action id={} operation={}", new Object[]{id, operation, exception});
    }

    public record Entry(ResourceLocation id, int order, Function<CompanionCommandTarget, Component> label, Predicate<CompanionCommandTarget> available, Predicate<CompanionCommandTarget> activate) {
