    private final Change change;
    private final MinecraftServer server;
    private final UUID ownerUuid;
    private final UUID companionUuid;
    private final CompanionDescriptor before;
    private final CompanionDescriptor after;
    private final long revision;

    public CompanionLifecycleEvent(MinecraftServer server, Change change, UUID ownerUuid, UUID companionUuid, CompanionDescriptor before, CompanionDescriptor after, long revision) {
        this.server = server;
        this.change = change;
        this.ownerUuid = ownerUuid;
        this.companionUuid = companionUuid;
        this.before = before;
        this.after = after;
        this.revision = Math.max(0L, revision);
    }

    public MinecraftServer server() {
        return this.server;
    }

    public Change change() {
        return this.change;
    }

    public UUID ownerUuid() {
        return this.ownerUuid;
    }

    public UUID companionUuid() {
        return this.companionUuid;
    }

    public Optional<CompanionDescriptor> before() {
        return Optional.ofNullable(this.before);
    }

    public Optional<CompanionDescriptor> after() {
        return Optional.ofNullable(this.after);
    }

    public long revision() {
        return this.revision;
    }

    public static enum Change {
        REGISTERED,
        DEPLOYED,
        STORED,
        RELEASED,
        DIED,
        RECOVERED,
        HOME_ASSIGNED,
        HOME_CLEARED,
        HOME_CHANGED,
        LIFECYCLE_CHANGED;

    }
}

