package com.kuzhi.findme.client;

import com.kuzhi.findme.client.ClientCompanionTeamState;
import com.kuzhi.findme.client.ClientCompanionWheelController;
import com.kuzhi.findme.common.CompanionKind;
import com.kuzhi.findme.common.CompanionMoveType;
import com.kuzhi.findme.common.CompanionTeamTarget;
import com.kuzhi.findme.network.CompanionListPacket;
import com.kuzhi.findme.network.DeadCompanionListPacket;
import com.kuzhi.findme.network.RecoveryCompanionListPacket;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.minecraft.nbt.CompoundTag;

public final class ClientCompanionState {
    private static final Map<CompanionKind, List<CompanionListPacket.Entry>> ENTRIES = new EnumMap<CompanionKind, List<CompanionListPacket.Entry>>(CompanionKind.class);
    private static final Map<CompanionKind, List<CompanionListPacket.Entry>> ALL_ENTRIES = new EnumMap<CompanionKind, List<CompanionListPacket.Entry>>(CompanionKind.class);
    private static final Map<CompanionKind, Integer> ACTIVE = new EnumMap<CompanionKind, Integer>(CompanionKind.class);
    private static final Map<CompanionKind, Long> SERVER_REVISIONS = new EnumMap<CompanionKind, Long>(CompanionKind.class);
    private static List<DeadCompanionListPacket.Entry> DEAD_ENTRIES = List.of();
    private static List<RecoveryCompanionListPacket.Entry> RECOVERY_ENTRIES = List.of();
    private static long revision;

    private ClientCompanionState() {
    }

    public static void update(CompanionKind kind, long serverRevision, int activeIndex, List<CompanionListPacket.Entry> entries, List<CompanionListPacket.Entry> allEntries) {
        if (serverRevision < ClientCompanionState.serverRevision(kind)) {
            return;
        }
        List<CompanionListPacket.Entry> previous = ClientCompanionState.previousEntries(kind);
        List<CompanionListPacket.Entry> merged = ClientCompanionState.mergePreviewTags(previous, entries);
        List<CompanionListPacket.Entry> mergedAll = ClientCompanionState.mergePreviewTags(previous, allEntries);
        ENTRIES.put(kind, List.copyOf(merged));
        ALL_ENTRIES.put(kind, List.copyOf(mergedAll));
        ACTIVE.put(kind, activeIndex);
        SERVER_REVISIONS.put(kind, serverRevision);
        ClientCompanionWheelController.observeRoster(kind, mergedAll.isEmpty() ? merged : mergedAll);
        ++revision;
    }

    public static List<CompanionListPacket.Entry> entries(CompanionKind kind) {
        List<CompanionListPacket.Entry> base = ClientCompanionState.filterUnavailableIntegrations(ENTRIES.getOrDefault((Object)kind, List.of()));
        List<UUID> members = ClientCompanionTeamState.currentMembers(kind == CompanionKind.MOUNT ? CompanionTeamTarget.MOUNT : CompanionTeamTarget.COMPANION);
        if (members.isEmpty()) {
            return base;
        }
        Map byUuid = ClientCompanionState.allEntries(kind).stream().collect(Collectors.toMap(CompanionListPacket.Entry::uuid, Function.identity(), (a, b) -> a));
        ArrayList<CompanionListPacket.Entry> preview = new ArrayList<CompanionListPacket.Entry>();
        for (UUID uuid : members) {
            CompanionListPacket.Entry entry = (CompanionListPacket.Entry)byUuid.get(uuid);
            if (entry == null) continue;
            preview.add(entry);
        }
        return preview.isEmpty() ? base : List.copyOf(preview);
    }

    public static List<CompanionListPacket.Entry> allEntries(CompanionKind kind) {
        List<CompanionListPacket.Entry> all = ALL_ENTRIES.getOrDefault((Object)kind, List.of());
        return ClientCompanionState.filterUnavailableIntegrations(all.isEmpty() ? ENTRIES.getOrDefault((Object)kind, List.of()) : all);
    }

    public static int activeIndex(CompanionKind kind) {
        List<CompanionListPacket.Entry> visible = ClientCompanionState.entries(kind);
        UUID activeUuid = ClientCompanionState.activeUuid(kind);
        if (activeUuid == null) {
            return -1;
        }
        for (int i = 0; i < visible.size(); ++i) {
            if (!activeUuid.equals(visible.get(i).uuid())) continue;
            return i;
        }
        return -1;
    }

    public static UUID activeUuid(CompanionKind kind) {
        int serverIndex = ACTIVE.getOrDefault((Object)kind, -1);
        List base = ENTRIES.getOrDefault((Object)kind, List.of());
        return serverIndex >= 0 && serverIndex < base.size() ? ((CompanionListPacket.Entry)base.get(serverIndex)).uuid() : null;
    }

    public static int serverWheelIndex(CompanionKind kind, UUID uuid) {
        List base = ENTRIES.getOrDefault((Object)kind, List.of());
        for (int i = 0; i < base.size(); ++i) {
            if (!((CompanionListPacket.Entry)base.get(i)).uuid().equals(uuid)) continue;
            return i;
        }
        return -1;
    }

